params.prompt:
New activity on the PR:

### New Comments
{{ JSON.stringify(JSON.parse(steps['check-pr-and-activity'].output).new_comments) }}

### New Commits
{{ JSON.parse(steps['check-pr-and-activity'].output).has_new_commits }}

Respond to comments. If there are new commits, review the changes and update your decision (APPROVE/REQUEST_CHANGES/COMMENT) accordingly.

steps.command:
node -e '
const initial = JSON.parse(process.env.INITIAL_OUTPUT).decision;
const reReviewOutput = process.env.RE_REVIEW_OUTPUT;
const final = reReviewOutput && reReviewOutput !== "undefined" && reReviewOutput.startsWith("{")
  ? JSON.parse(reReviewOutput).decision
  : initial;
const state = process.env.FINAL_STATE.trim();

let category = "neutral";
if (initial === "COMMENT" || final === "COMMENT") {
  category = "neutral";
} else {
  const key = `${initial}_${final}_${state}`;
  const categories = {
    "APPROVE_APPROVE_MERGED": "effective",
    "APPROVE_APPROVE_CLOSED": "neutral",
    "REQUEST_CHANGES_APPROVE_MERGED": "effective",
    "REQUEST_CHANGES_APPROVE_CLOSED": "neutral",
    "REQUEST_CHANGES_REQUEST_CHANGES_MERGED": "overridden",
    "REQUEST_CHANGES_REQUEST_CHANGES_CLOSED": "effective",
    "APPROVE_REQUEST_CHANGES_MERGED": "overridden",
    "APPROVE_REQUEST_CHANGES_CLOSED": "effective",
  };
  category = categories[key] || "neutral";
}

console.log(JSON.stringify({
  initial_decision: initial,
  final_decision: final,
  final_state: state,
  decision_changed: initial !== final,
  is_effective: category === "effective" ? 1 : 0,
  is_overridden: category === "overridden" ? 1 : 0
}));
'
